 private void inventoryEdit(JSONObject character,JSONObject record){try{LinearLayout l=form();Spinner account=accountsChoice(l,record==null?accountFilter:record.getString("account_id"));TextView count=countPicker(l,"同じ育成状態でまとめて登録する体数",record==null?1:record.getInt("count"));EditText luck=input(l,"ラック（1体あたりのメモ）",record==null?"0":record.getString("luck"),true);EditText fruit=input(l,"現在のわくわくの実",record==null?"":record.getString("fruit"),false);EditText target=input(l,"付けたい実・厳選目標",record==null?"":record.getString("target_fruit"),false);CheckBox done=flag(l,"育成・厳選が完了",record!=null&&record.getBoolean("trained"));EditText memo=input(l,"育成・紋章・その他メモ",record==null?"":record.getString("memo"),false);removeButton(l,"inventory",record);
  dialog(character.getString("name"),l,copy->{int quantity=Integer.parseInt(count.getText().toString());if(quantity==0){if(record!=null)copy.planner().delete("inventory",record.getString("id"));return;}JSONObject r=record==null?fresh():new JSONObject(record.toString());r.put("catalog_id",character.getString("id")).put("name",character.getString("name")).put("element",character.getString("element")).put("form",character.getString("form")).put("icon",!character.optString("icon","").isEmpty()?character.optString("icon"):!character.optString("no","").isEmpty()?character.optString("no"):record==null?"":record.optString("icon","")).put("account_id",accountValue(account)).put("count",Integer.parseInt(count.getText().toString())).put("luck",Integer.parseInt(luck.getText().toString())).put("fruit",fruit.getText().toString()).put("target_fruit",target.getText().toString()).put("trained",done.isChecked()).put("memo",memo.getText().toString());copy.planner().put("inventory",r);});}catch(Exception e){error(e);}}
