 private void trainingList(){try{LinearLayout l=form();JSONArray a=state.planner().list("inventory");int count=0;for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i);if(r.getBoolean("trained"))continue;count++;action(l,state.account(r.getString("account_id")).getString("name")+" / "+r.getString("name")+"\n現在："+r.getString("fruit")+"\n目標："+r.getString("target_fruit"),()->{try{JSONObject c=new JSONObject().put("id",r.getString("catalog_id")).put("name",r.getString("name")).put("element",r.getString("element")).put("form",r.getString("form"));inventoryEdit(c,r);}catch(Exception e){error(e);}});}if(count==0)l.addView(text("育成中の所持キャラはありません",15,WHITE));new AlertDialog.Builder(this).setTitle("厳選・育成リスト").setView(formScroll(l)).setPositiveButton("閉じる",null).show();}catch(Exception e){error(e);}}
 private void teamsPage()throws Exception{title("4垢チーム・まとめてチェック");action(body,"＋ チームを登録",()->teamEdit(null));JSONArray ts=state.planner().list("teams");for(int i=0;i<ts.length();i++){JSONObject t=ts.getJSONObject(i);LinearLayout c=card();c.addView(text(t.getString("name"),18,WHITE));JSONArray ms=t.getJSONArray("members");StringBuilder names=new StringBuilder();for(int j=0;j<ms.length();j++)names.append(state.account(ms.getString(j)).getString("name")).append("  ");c.addView(text(names.toString(),14,MUTED));action(c,"メンバー編集",()->teamEdit(t));action(c,"まとめて完了／未完了にする",()->teamCheck(t));}}
 private void teamEdit(JSONObject old){try{LinearLayout l=form();EditText name=input(l,"チーム名",old==null?"":old.getString("name"),false);java.util.List<CheckBox> checks=new java.util.ArrayList<>();java.util.List<String> ids=new java.util.ArrayList<>();String selected=old==null?"":old.getJSONArray("members").toString();for(int i=0;i<state.accounts().length();i++){JSONObject a=state.accounts().getJSONObject(i);ids.add(a.getString("id"));checks.add(flag(l,a.getString("name"),selected.contains(a.getString("id"))));}removeButton(l,"teams",old);dialog("1〜4垢を選択",l,copy->{JSONArray members=new JSONArray();for(int i=0;i<checks.size();i++)if(checks.get(i).isChecked())members.put(ids.get(i));JSONObject r=old==null?fresh():new JSONObject(old.toString());r.put("name",name.getText().toString()).put("members",members);copy.planner().put("teams",r);});}catch(Exception e){error(e);}}
 private void teamCheck(JSONObject t){try{LinearLayout l=form();String[] names=new String[state.tasks().length()+1],keys=new String[names.length];names[0]="絆";keys[0]="bond";for(int i=1;i<names.length;i++){JSONObject task=state.tasks().getJSONObject(i-1);names[i]=task.getString("name");keys[i]=task.getString("id");}Spinner task=choice(l,"まとめて変更する項目",names,0);CheckBox done=flag(l,"完了にする（外すと未完了）",true);dialog(t.getString("name"),l,copy->copy.planner().teamCheck(t.getString("id"),keys[task.getSelectedItemPosition()],done.isChecked(),Instant.now()));}catch(Exception e){error(e);}}
 private static final class DeadlineForm{EditText date,time,lead;CheckBox notify;void apply(JSONObject r)throws Exception{String d=date.getText().toString().trim();String due=d.isEmpty()?"":LocalDateTime.of(LocalDate.parse(d),LocalTime.parse(time.getText().toString().trim())).atZone(ZoneId.of("Asia/Tokyo")).toOffsetDateTime().toString();r.put("due",due).put("notify",!due.isEmpty()&&notify.isChecked()).put("lead_hours",Integer.parseInt(lead.getText().toString().trim()));}}
 private DeadlineForm deadline(LinearLayout l,JSONObject old)throws Exception{DeadlineForm d=new DeadlineForm();String due=old==null?"":old.optString("due","");OffsetDateTime at=due.isEmpty()?null:OffsetDateTime.parse(due);d.date=input(l,"終了日 YYYY-MM-DD（任意）",at==null?"":at.toLocalDate().toString(),false);d.time=input(l,"終了時刻 HH:mm（日本時間）",at==null?"23:59":at.toLocalTime().toString(),false);d.notify=flag(l,"終了前に端末へ通知",old!=null&&old.optBoolean("notify"));d.lead=input(l,"何時間前に通知するか（0〜168）",old==null?"24":String.valueOf(old.optInt("lead_hours",24)),true);return d;}
 private boolean onlyPending=false;
 private void missionsPage()throws Exception{title("月間・期間限定ミッション");action(body,"＋ ミッションを追加",()->missionEdit(null));CheckBox pending=flag(body,"未受取のミッションだけ表示",onlyPending);pending.setOnCheckedChangeListener((b,on)->{onlyPending=on;render();});JSONArray ms=state.planner().list("missions");java.util.List<JSONObject> rows=new java.util.ArrayList<>();for(int i=0;i<ms.length();i++)rows.add(ms.getJSONObject(i));rows.sort(java.util.Comparator.comparing(r->r.optString("due").isEmpty()?"9999":r.optString("due")));for(JSONObject m:rows){JSONObject progress=m.getJSONObject("progress");int received=0;for(int j=0;j<state.accounts().length();j++)if(progress.optInt(state.accounts().getJSONObject(j).getString("id"),0)==3)received++;if(onlyPending&&received==state.accounts().length())continue;LinearLayout c=card();c.addView(text(m.getString("name")+" / "+m.getString("period"),18,WHITE));c.addView(text("報酬受取済 "+received+"/"+state.accounts().length()+"垢\n期限："+dueLabel(m),14,BLUE));action(c,"各垢の進捗を変更",()->missionProgress(m));action(c,"内容・期限を編集",()->missionEdit(m));action(c,"翌月用に複製（進捗は初期化）",()->new AlertDialog.Builder(this).setTitle("翌月用に複製しますか？").setMessage("期間・期限を1か月進め、進捗を未着手にします。実際の開催日程は編集で確認してください。").setNegativeButton("キャンセル",null).setPositiveButton("複製",(d,w)->change(copy->{JSONObject r=new JSONObject(m.toString());r.put("id",PlannerData.id()).put("period",YearMonth.parse(m.getString("period")).plusMonths(1).toString()).put("progress",new JSONObject());if(!m.getString("due").isEmpty())r.put("due",OffsetDateTime.parse(m.getString("due")).plusMonths(1).toString());r.remove("notified_due");copy.planner().put("missions",r);},true)).show());}}
 private String dueLabel(JSONObject r){String d=r.optString("due");if(d.isEmpty())return "未設定";try{return OffsetDateTime.parse(d).atZoneSameInstant(ZoneId.of("Asia/Tokyo")).format(DateTimeFormatter.ofPattern("yyyy/MM/dd HH:mm"));}catch(Exception e){return d;}}
 private void missionEdit(JSONObject old){try{LinearLayout l=form();EditText name=input(l,"ミッション名",old==null?"":old.getString("name"),false);EditText period=input(l,"管理する月 YYYY-MM",old==null?YearMonth.now(ZoneId.of("Asia/Tokyo")).toString():old.getString("period"),false);EditText memo=input(l,"メモ",old==null?"":old.getString("memo"),false);DeadlineForm df=deadline(l,old);removeButton(l,"missions",old);dialog("月間・限定ミッション",l,copy->{JSONObject r=old==null?fresh().put("progress",new JSONObject()):new JSONObject(old.toString());r.put("name",name.getText().toString()).put("period",period.getText().toString().trim()).put("memo",memo.getText().toString());df.apply(r);copy.planner().put("missions",r);});}catch(Exception e){error(e);}}
 private void missionProgress(JSONObject m){try{LinearLayout l=form();java.util.List<Spinner> choices=new java.util.ArrayList<>();java.util.List<String> ids=new java.util.ArrayList<>();String[] statuses={"未着手","途中","クリア済","報酬受取済"};for(int i=0;i<state.accounts().length();i++){JSONObject a=state.accounts().getJSONObject(i);ids.add(a.getString("id"));choices.add(choice(l,a.getString("name"),statuses,m.getJSONObject("progress").optInt(a.getString("id"),0)));}dialog(m.getString("name"),l,copy->{JSONObject r=copy.planner().find("missions",m.getString("id"));JSONObject progress=new JSONObject();for(int i=0;i<ids.size();i++)progress.put(ids.get(i),choices.get(i).getSelectedItemPosition());r.put("progress",progress);});}catch(Exception e){error(e);}}
 private void goalsPage()throws Exception{title("運極・周回目標");action(body,"＋ 目標を登録",()->goalEdit(null));JSONArray a=state.planner().list("goals");for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i);LinearLayout c=card();int left=Math.max(0,r.getInt("target")-r.getInt("current"));c.addView(text(r.getString("name"),18,WHITE));c.addView(text(state.account(r.getString("account_id")).getString("name")+" / "+r.getInt("current")+" → "+r.getInt("target")+"（残り"+left+"）\n期限："+dueLabel(r),14,BLUE));c.addView(text(r.getString("memo"),14,MUTED));action(c,"進捗・目標を編集",()->goalEdit(r));}}
 private void goalEdit(JSONObject old){try{LinearLayout l=form();Spinner account=accountsChoice(l,old==null?"":old.getString("account_id"));EditText name=input(l,"キャラ・クエスト・目標名",old==null?"":old.getString("name"),false);EditText current=input(l,"現在のラック・周回数",old==null?"0":old.getString("current"),true);EditText target=input(l,"目標",old==null?"99":old.getString("target"),true);EditText memo=input(l,"使用チーム・周回メモ",old==null?"":old.getString("memo"),false);DeadlineForm df=deadline(l,old);removeButton(l,"goals",old);dialog("運極・周回目標",l,copy->{JSONObject r=old==null?fresh():new JSONObject(old.toString());r.put("account_id",accountValue(account)).put("name",name.getText().toString()).put("current",Integer.parseInt(current.getText().toString())).put("target",Integer.parseInt(target.getText().toString())).put("memo",memo.getText().toString());df.apply(r);copy.planner().put("goals",r);});}catch(Exception e){error(e);}}
 private String imageFormationId="";
 private void formationsPage()throws Exception{title("攻略編成ノート");action(body,"＋ 編成を保存",()->formationEdit(null));JSONArray a=state.planner().list("formations");for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i);LinearLayout c=card();c.addView(text(r.getString("name"),18,WHITE));JSONArray m=r.getJSONArray("members");for(int j=0;j<m.length();j++){JSONObject slot=m.getJSONObject(j);c.addView(text((j+1)+"枠："+state.account(slot.getString("account_id")).getString("name")+" / "+slot.getString("character"),14,BLUE));}c.addView(text(r.getString("memo"),14,MUTED));action(c,"編成・攻略メモを編集",()->formationEdit(r));action(c,"スクショを添付・差し替え",()->pickFormationImage(r.optString("id")));if(!r.getString("image").isEmpty()){action(c,"添付画像を見る",()->showFormationImage(r.optString("image")));action(c,"添付画像を外す",()->new AlertDialog.Builder(this).setTitle("画像を外しますか？").setNegativeButton("キャンセル",null).setPositiveButton("外す",(d,w)->change(copy->copy.planner().find("formations",r.optString("id")).put("image",""),true)).show());}}}
 private void formationEdit(JSONObject old){try{LinearLayout l=form();EditText name=input(l,"クエスト・編成名",old==null?"":old.getString("name"),false);java.util.List<Spinner> accounts=new java.util.ArrayList<>();java.util.List<EditText> chars=new java.util.ArrayList<>();JSONArray previous=old==null?new JSONArray():old.getJSONArray("members");for(int i=0;i<4;i++){JSONObject slot=i<previous.length()?previous.getJSONObject(i):null;l.addView(text((i+1)+"枠目（キャラ名が空欄なら未登録）",16,BLUE));accounts.add(accountsChoice(l,slot==null?"":slot.getString("account_id")));chars.add(input(l,"キャラ名・形態",slot==null?"":slot.getString("character"),false));}EditText memo=input(l,"実・紋章・手順・注意点",old==null?"":old.getString("memo"),false);removeButton(l,"formations",old);dialog("攻略編成",l,copy->{JSONArray m=new JSONArray();for(int i=0;i<4;i++){String nameValue=chars.get(i).getText().toString().trim();if(!nameValue.isEmpty())m.put(new JSONObject().put("account_id",accountValue(accounts.get(i))).put("character",nameValue));}JSONObject r=old==null?fresh().put("image",""):new JSONObject(old.toString());r.put("name",name.getText().toString()).put("members",m).put("memo",memo.getText().toString());copy.planner().put("formations",r);});}catch(Exception e){error(e);}}
 private void pickFormationImage(String id){imageFormationId=id;try{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,412);}catch(Exception e){error(e);}}
 private void importFormationImage(Uri uri){String recordId=imageFormationId;if(recordId.isEmpty()){toast("編成を選び直してください");return;}io.execute(()->{try{android.graphics.BitmapFactory.Options opt=new android.graphics.BitmapFactory.Options();opt.inJustDecodeBounds=true;try(InputStream in=getContentResolver().openInputStream(uri)){android.graphics.BitmapFactory.decodeStream(in,null,opt);}if(opt.outWidth<=0||opt.outHeight<=0)throw new IOException("画像を読み込めません");opt.inSampleSize=1;while(Math.max(opt.outWidth,opt.outHeight)/opt.inSampleSize>1280)opt.inSampleSize*=2;opt.inJustDecodeBounds=false;android.graphics.Bitmap bitmap;try(InputStream in=getContentResolver().openInputStream(uri)){bitmap=android.graphics.BitmapFactory.decodeStream(in,null,opt);}if(bitmap==null)throw new IOException("画像を開けません");ByteArrayOutputStream out=new ByteArrayOutputStream();bitmap.compress(android.graphics.Bitmap.CompressFormat.JPEG,80,out);bitmap.recycle();if(out.size()>1400000)throw new IOException("画像が大きすぎます");String image=java.util.Base64.getEncoder().encodeToString(out.toByteArray());handler.post(()->{if(!isDestroyed())change(copy->copy.planner().find("formations",recordId).put("image",image),true);});}catch(Exception e){handler.post(()->{if(!isDestroyed())error(e);});}});}
 private void showFormationImage(String image){try{byte[] b=java.util.Base64.getDecoder().decode(image);android.graphics.Bitmap bmp=android.graphics.BitmapFactory.decodeByteArray(b,0,b.length);if(bmp==null)throw new IOException("画像を表示できません");ImageView view=new ImageView(this);view.setAdjustViewBounds(true);view.setImageBitmap(bmp);new AlertDialog.Builder(this).setTitle("攻略スクショ").setView(view).setPositiveButton("閉じる",null).show();}catch(Exception e){error(e);}}
 private void orbPlansPage()throws Exception{title("オーブ目標・獲得予定");action(body,"＋ 獲得予定を登録",()->orbPlanEdit(null));for(int i=0;i<state.accounts().length();i++){JSONObject a=state.accounts().getJSONObject(i);String id=a.getString("id");LinearLayout c=card();long expected=state.planner().expectedOrbs(id);int target=state.planner().orbTarget(id);c.addView(text(a.getString("name"),18,WHITE));c.addView(text("現在 "+a.getInt("orbs")+" / 目標 "+target+"\n未回収予定 +"+expected+" / 回収後の見込み "+((long)a.getInt("orbs")+expected),14,BLUE));action(c,"目標数を変更",()->{LinearLayout l=form();EditText v=input(l,"目標オーブ数",String.valueOf(target),true);dialog("オーブ目標",l,copy->copy.planner().setOrbTarget(id,Integer.parseInt(v.getText().toString())));});}
  JSONArray a=state.planner().list("orb_plans");for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i);LinearLayout c=card();c.addView(text(r.getString("name")+" +"+r.getInt("amount")+"個",18,WHITE));c.addView(text(state.account(r.getString("account_id")).getString("name")+" / "+(r.getBoolean("received")?"回収済":"未回収")+"\n期限："+dueLabel(r),14,MUTED));if(!r.getBoolean("received")){action(c,"回収して残高へ加算",()->new AlertDialog.Builder(this).setTitle("現在の残高に加算しますか？").setMessage("すでに残高を手入力で増やしている場合は、二重加算にご注意ください。").setNegativeButton("キャンセル",null).setPositiveButton("加算",(d,w)->change(copy->copy.planner().collect(r.optString("id"),Instant.now()),true)).show());action(c,"残高を変えず回収済みにする",()->change(copy->copy.planner().find("orb_plans",r.getString("id")).put("received",true),true));}action(c,"予定を編集",()->orbPlanEdit(r));}}
 private void orbPlanEdit(JSONObject old){try{LinearLayout l=form();Spinner account=accountsChoice(l,old==null?"":old.getString("account_id"));EditText name=input(l,"獲得予定の内容",old==null?"":old.getString("name"),false);EditText amount=input(l,"獲得予定の数",old==null?"1":old.getString("amount"),true);DeadlineForm df=deadline(l,old);removeButton(l,"orb_plans",old);dialog("オーブ獲得予定",l,copy->{JSONObject r=old==null?fresh().put("received",false):new JSONObject(old.toString());if(old!=null&&old.getBoolean("received"))throw new IllegalArgumentException("回収済みの記録は変更できません。誤記録は削除して登録し直してください");r.put("account_id",accountValue(account)).put("name",name.getText().toString()).put("amount",Integer.parseInt(amount.getText().toString()));df.apply(r);copy.planner().put("orb_plans",r);});}catch(Exception e){error(e);}}
 private void enableNotifications(){if(android.os.Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},413);}else{DeadlineScheduler.schedule(this);toast("期限通知を設定しました。各記録でも通知をONにしてください");}}
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] result){super.onRequestPermissionsResult(r,p,result);if(r==413){if(result.length>0&&result[0]==android.content.pm.PackageManager.PERMISSION_GRANTED){DeadlineScheduler.schedule(this);toast("通知を有効にしました");}else toast("通知はOFFのままです。管理機能は利用できます");}}

